<style lang="scss" src="./share-modal.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import SimpleGrid from "../simple-grid/simple-grid";
import { SimpleGridAlign } from "../simple-grid/simple-grid.contants";
import {
  destroyModalRootContent,
  ensureModalRoot,
} from "../../util/ensure-modal-root";
import { MountingPortal } from "portal-vue";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";
import Button from "../button/button";
import { ButtonMode, ButtonSize } from "../button/button.constants";
import WrapNode from "../wrap-node/wrap-node";
import ScrollView from "../scroll-view/scroll-view";

/**
 * Displays a modal with content specific to Sharing via media platforms.
 */
@Component({
  components: {
    MountingPortal,
    SimpleGrid,
    Icon,
    Button,
    WrapNode,
    ScrollView,
  },
})
export default class ShareModal extends Vue {
  /** The title to display at the top of the modal */
  @Prop({ type: String }) title;
  /** Will display a link that can be easily copied for the user to share. */
  @Prop({ type: String }) link;
  /** Will display the tip with a title provided */
  @Prop({ type: String }) tipTitle;
  /** Will display the tip with this as body content */
  @Prop({ type: String }) tipBody;
  /** Label for the button in the tip region */
  @Prop({ type: String }) tipButton;

  /**
   * This is the root modal element the menu resides in to render floating above
   * all the other elements in the DOM.
   */
  modalRoot = null;

  // Enums
  IconShape = IconShape;
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;
  SimpleGridAlign = SimpleGridAlign;

  get modalRootId() {
    return `#${this.modalRoot.id}`;
  }

  get containerStyle() {
    return {
      height: `${window.innerHeight}px`,
    };
  }

  get hasTip() {
    return this.tipTitle || this.tipBody;
  }

  get hasChildren() {
    return this.children.length > 0;
  }

  get children() {
    let slots = this.$slots.default;

    if (!Array.isArray(slots)) {
      slots = [slots];
    }

    return slots.filter((s) => Boolean(s && s.tag));
  }

  beforeMount() {
    // HACK: MountingPortal spawns mass duplicates. So as Thanos once said:
    //       Fine. I'll do it myself
    destroyModalRootContent("Menu");
    this.modalRoot = ensureModalRoot();

    if (!this.modalRoot) {
      console.warn("Could not establish modal root for floating componentry");
      return;
    }

    window.addEventListener("resize", this.handleResize);
  }

  beforeDestroy() {
    window.removeEventListener("resize", this.handleResize);
  }

  /**
   * HACKY HACKS: Due to vue portal having it's own set of issues and we handle
   * its DOM disposal manually, this causes certain scenarios to throw errors
   * from the MountingPortal component. So, we just absorb those issues here for
   * now until better solutions can be discovered or Vue3 is used with better
   * native made portals.
   */
  errorCaptured(err, vm, info) {
    if (info === "beforeDestroy hook") {
      return false;
    }
  }

  handleResize() {
    this.$forceUpdate();
  }

  handleClose() {
    /**
     * Emitted when it is detected that the user wishes for this modal to be
     * closed.
     *
     * @event close
     */
    this.$emit("close");
  }

  handleCloseOutside(e) {
    if (e.target !== this.$refs.container) return;
    this.handleClose();
    e.stopPropagation();
    e.preventDefault();
  }

  handleCopy() {
    /**
     * Emitted when the user intends to copy the contents of the link to their
     * clip board. This component does NOT perform the copy to the clip board
     * itself as the operation is generally handled through libraries of choice.
     *
     * @event copy
     */
    this.$emit("copy");

    try {
      this.$refs.link.select();
      this.$refs.link.select();
      this.$refs.link.setSelectionRange(0, 99999);
      document.execCommand("copy");
    } catch (err) {
      // Could not copy
    }
  }

  handleClickTip() {
    /**
     * Emitted when user clicks the button within the tip section.
     *
     * @event tip
     */
    this.$emit("tip");
  }
}
</script>

<template>
  <MountingPortal :mountTo="modalRootId" append>
    <div
      class="ShareModal"
      :style="containerStyle"
      ref="container"
      @click="handleCloseOutside"
    >
      <div class="ShareModal__Content">
        <Icon
          class="ShareModal__Close"
          :shape="IconShape.CLOSE"
          :size="14"
          @click="handleClose"
        />
        <div class="ShareModal__Head">
          <span>{{ title }}</span>
        </div>
        <div class="ShareModal__Body">
          <ScrollView class="ShareModal__Scroll">
            <div class="ShareModal__BodyContent">
              <SimpleGrid
                v-if="hasChildren"
                :align="SimpleGridAlign.CENTER"
                :columnWidth="108"
                :rowHeight="128"
              >
                <slot />
              </SimpleGrid>
              <div v-if="link">
                <div class="ShareModal__LinkTitle">Page Link</div>
                <div class="ShareModal__Link">
                  <input
                    type="text"
                    readonly
                    class="ShareModal__LinkValue"
                    :value="link"
                    ref="link"
                  />
                  <Icon
                    class="ShareModal__LinkCopy"
                    :shape="IconShape.COPY"
                    :size="16"
                    @click="handleCopy"
                  />
                </div>
              </div>
              <div v-if="hasTip" class="ShareModal__Tip">
                <div v-if="tipTitle" class="ShareModal__TipTitle">
                  {{ tipTitle }}
                </div>
                <div v-if="tipBody" class="ShareModal__TipBody">
                  {{ tipBody }}
                </div>
                <Button
                  v-if="tipButton"
                  class="ShareModal__TipButton"
                  :mode="ButtonMode.PRIMARY"
                  :size="ButtonSize.LARGE"
                  :label="tipButton"
                  @click="handleClickTip"
                />
              </div>
            </div>
          </ScrollView>
        </div>
      </div>
    </div>
  </MountingPortal>
</template>
